package com.apple.android.music.playback.queue;import java.util.*;import com.apple.android.music.model.CollectionItemView;public class LibraryItemListPlaybackQueueItemProvider {public static class Builder {private final PlaybackQueueItemProvider value=new PlaybackQueueItemProvider();public Builder dataSource(Z6.f source,CollectionItemView selected){value.rows=new ArrayList<>();for(int i=0;i<source.getItemCount();i++)value.rows.add(source.getItemAtIndex(i));return this;}public Builder startItemIndex(int index){value.index=index;return this;}public PlaybackQueueItemProvider build(){return value;}}}